  url_parse: 'URL parsing failed.',
  dns_lookup: 'DNS lookup failed.',
  ip_validation: 'Destination address was blocked.',
  request_setup: 'Outbound request setup failed.',
  tcp_connect: 'TCP connection failed.',
  tls_handshake: 'TLS handshake failed.',
  http_request: 'HTTP request failed.',
  redirect_processing: 'Redirect response was invalid.',
  redirect_dns_validation: 'Redirect destination validation failed.'
