}

function isBlockedHostname(hostname) {
  const host = String(hostname || '').toLowerCase().replace(/\.$/, '');
  if (!host || host === 'localhost' || host.startsWith('localhost.') || host.endsWith('.localhost') || host.endsWith('.local')) return true;
  if (host.endsWith('.internal') || host.endsWith('.lan') || host.endsWith('.home') || host.endsWith('.corp')) return true;
  if (!net.isIP(host) && !host.includes('.')) return true;
  if (/^(?:0x[0-9a-f]+|\d+)$/i.test(host)) return true;
  return false;
}

async function validateTarget(parsed) {
  const hostname = parsed.hostname.toLowerCase().replace(/\.$/, '');
  if (isBlockedHostname(hostname)) {
    throw resolverError('blocked_destination', 'ip_validation', null);
  }
  const literalFamily = net.isIP(hostname);
  let addresses;
  if (literalFamily) {
    addresses = [{ address: hostname, family: literalFamily }];
  } else {
    try {
      addresses = await dns.lookup(hostname, { all: true, verbatim: true });
    } catch (cause) {
      throw resolverError('dns_failure', 'dns_lookup', cause);
    }
  }
  if (!Array.isArray(addresses) || addresses.length === 0) {
    throw resolverError('dns_failure', 'dns_lookup', null);
  }
