async function sendMetadataRequest(parsed, pinnedAddress) {
  const head = await requestOnce(parsed, 'HEAD', pinnedAddress);
  if (head.status_code === 405 || head.status_code === 501) {
    return requestOnce(parsed, 'GET', pinnedAddress);
  }
  return head;
}

async function resolveShortUrl(original) {
  let current = original.parsed;
  let redirectCount = 0;
  for (;;) {
    const pinnedAddress = await validateTarget(current);
    const response = await sendMetadataRequest(current, pinnedAddress);
    if (!REDIRECT_STATUSES.has(response.status_code)) {
