      recordFailure(resolverError('invalid_redirect', 'redirect_processing', null), 'redirect_processing');
      return safeResult(original.hostname, true, 'invalid_redirect', { redirect_count: redirectCount });
    }
    let destination;
    try {
      destination = new URLClass(response.location, current);
    } catch (cause) {
      recordFailure(resolverError('invalid_redirect', 'redirect_processing', cause), 'redirect_processing');
      return safeResult(original.hostname, true, 'invalid_redirect', { redirect_count: redirectCount });
