    if (!parsedDestination.ok) {
      const status = parsedDestination.status === 'blocked_destination' ? 'blocked_destination' : 'invalid_redirect';
      recordFailure(resolverError(status, 'redirect_processing', null), 'redirect_processing');
      return safeResult(original.hostname, true, status, { redirect_count: redirectCount });
    }
    try {
      await validateTarget(parsedDestination.parsed);
    } catch (error) {
      error.safe_stage = 'redirect_dns_validation';
      recordFailure(error, 'redirect_dns_validation');
      return safeResult(original.hostname, true, error.resolution_status || 'blocked_destination', { redirect_count: redirectCount });
    }
    current = parsedDestination.parsed;
    redirectCount += 1;
  }
}

function extractCandidates(content) {
  const pattern = /\b[a-z][a-z0-9+.-]*:\/\/[^\s<>"']+/gi;
  const seen = new Set();
  const output = [];
  for (const match of content.matchAll(pattern)) {
    if (output.length >= MAX_DETECTED_URLS) break;
    const parsed = parseUrl(match[0]);
    const key = parsed.ok ? parsed.normalized_url : trimUrlPunctuation(match[0]).toLowerCase();
    if (!key || seen.has(key)) continue;
    seen.add(key);
    output.push(parsed);
  }
  return output;
}

