      urls_attempted: attempted,
      urls_resolved: resolved,
      results
    },
    internal_diagnostics: {
      url_resolver: {
        automatic_redirects: false,
        dns_validation_per_hop: true,
        request_timeout_ms: REQUEST_TIMEOUT_MS,
        max_redirects: MAX_REDIRECTS,
        failures: diagnosticFailures
